{% import "templates/emails/macros.html" as utils %}

{% block content %}

	<div class="bg-white">
		<p class="mb-6">
		    The trial period of your {{ product.title }} site <strong>{{ site.host_name }}</strong> has ended on {{ frappe.utils.getdate(site.trial_end_date).strftime('%d %B, %Y') }}.
		    Your site will now be suspended. Choose a plan and add your billing information for your site to resume service.
		</p>
		{{ utils.button('Open Dashboard', frappe.get_url('/dashboard/sites/' + site.name)) }}
		{{ utils.separator() }}
		{{ utils.signature() }}
	</div>

{% endblock %}
